// Who shares the feeds, filled in when the template is added.
const WHO = {{who}};
// The widget turns red once the last feed is this many minutes old.
const DUE = 3 * 60;
// One dot per feed in the last day, up to this many.
const DOTS = 8;
const TEAL = '#12343b';
const RED = '#a3303d';
const FOAM = '#e6fff8';
const BOTTLE = 'M9 2.5h6M10 2.5v3l-2 3v11a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2v-11l-2-3v-3 M8 13h8';

function since(minutes) {
  if (minutes < 1) return 'just now';
  if (minutes < 60) return minutes + 'm';
  const rest = minutes % 60;
  return Math.floor(minutes / 60) + 'h ' + (rest < 10 ? '0' : '') + rest + 'm';
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the time are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const wide = ctx.family === 'medium';
  const recent = ctx.data.recent;
  const last = recent[0];
  const late = !!last && last.minutesAgo >= DUE;
  const tone = late ? '#ffd0d8' : '#7fe0c8';
  const fed = recent.filter((feed) => feed.minutesAgo < 24 * 60).length;
  const who = last && (last.by.me ? 'you' : last.by.name || WHO);
  const dot = (wide ? 9 : 7) * u;
  const key = (action, child) => ({ type: 'button', action, children: [
    { type: 'zstack', frame: { width: (wide ? 56 : 44) * u, height: 36 * u },
      background: { type: 'rect', cornerRadius: 11 * u, fill: '#FFFFFF29' }, children: [child] } ] });
  const letter = (value) => ({ type: 'text', value, size: 15 * u, weight: 'heavy', color: FOAM });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: late ? RED : TEAL,
    children: [
      { type: 'vstack', align: 'leading', spacing: 0,
        padding: { top: 15 * u, leading: 16 * u, trailing: (wide ? 88 : 72) * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: BOTTLE, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
              stroke: { color: tone, width: 2.4 * 15 * u / 24 } },
            { type: 'text', value: 'Last feed', size: 13 * u, weight: 'bold', color: tone, lineLimit: 1,
              minScale: 0.8 } ] },
          { type: 'text', value: last ? since(last.minutesAgo) : 'No feeds', fontName: 'Bricolage Grotesque Display',
            size: 36 * u, kerning: -1.08 * u, color: FOAM, accent: true, lineLimit: 1, minScale: 0.5,
            padding: { top: 4.4 * u } },
          { type: 'text', value: last ? (last.side || 'Fed') + ', by ' + who : 'tap after a feed,\nyou or ' + WHO,
            size: 12.5 * u, weight: 'semibold', color: FOAM, opacity: 0.8, lineLimit: last ? 1 : 2,
            minScale: last ? 0.6 : 0.3, padding: { top: 1.4 * u } },
          { type: 'hstack', spacing: (wide ? 4 : 3) * u, padding: { top: 12 * u }, children:
            Array.from({ length: DOTS }, (_, i) => ({ type: 'circle', fill: i < fed ? tone : '#FFFFFF38',
              frame: { width: dot, height: dot } })) },
        ] },
      { type: 'vstack', spacing: 8 * u, padding: { top: 15 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
        children: [
          key('left', letter('L')),
          key('right', letter('R')),
          key('bottle', { type: 'path', d: BOTTLE, viewBox: [0, 0, 24, 24], frame: { width: 18 * u, height: 18 * u },
            stroke: { color: FOAM, width: 2.4 * 18 * u / 24 } }),
        ] },
      last && last.by.me && last.minutesAgo < 10 && { type: 'zstack', padding: { leading: 10 * u, bottom: 8 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
        children: [
          { type: 'button', action: 'undo', rowId: last.id, children: [
            { type: 'symbol', name: 'arrow.uturn.backward', size: 12, weight: 'bold', color: FOAM,
              frame: { width: 30, height: 30 }, background: '#e6fff822', clip: 'circle' } ] },
        ] },
    ],
  };
}
